          const parts = x.text.split(/(\[[^\]]+\]|\{[^}]+\})/).filter((s) => s !== '');
          const iS = parts.findIndex((s) => s[0] === '['), iC = parts.findIndex((s) => s[0] === '{'), subjFirst = iS < iC;
          // the key underlines the WHOLE subject (both parts of a subject joined by and) and its arrow, under the line,
