            const arc = `<span data-lcs-arc style="position:absolute;left:${(L - 1.5).toFixed(1)}px;right:${(Rr - 1.5).toFixed(1)}px;top:calc(100% + 4px);height:13px;border:3px solid ${T.teal};border-top:none;border-radius:0 0 10px 10px;box-sizing:border-box"></span>`;
