        const okAt = pick('right rows', () => { if (!d.ok) return []; const p = shuffle([...Array(d.n).keys()].slice(1, -1), rng).slice(0, d.ok).sort((a, b) => a - b); return p.some((x, i) => i && x === p[i - 1] + 1) ? null : p; });
        const legRows = AGREE_ROWS[lv].map((k2) => `<div data-lcs-legrow="${k2}" data-lcs-read style="font:700 17px/1.24 'Nunito',sans-serif;color:${T.ink}">${esc(AGREE_LEG[k2])}</div>`);
        blocks.push(legendCard('data-lcs-agreeleg="1"', legRows));
        const what = lv === 3 ? 'the verb or pronoun' : 'the verb';
        blocks.push(label(`${num(1)}Cross out ${what} that does not agree. Write the right word on the line.${d.ok ? ' If a sentence is right, put a check mark on its line.' : ''}`, 18, 'data-lcs-fixtask'));
        const PX = 20;
