    const pool = BANK.plural.nouns.filter((x) => (lv === 1 || x.rule !== 1) && rules.includes(x.rule) && (x.rule !== 1 || !x.ay || rules.includes(3)) && x.wrong.length >= 1 && x.wrong.length + (x.s !== x.p ? 1 : 0) >= opts - 1 && (lv > 1 || x.rule !== 1 || !x.ay));
