      if (new Set(reg.map((v) => v.move)).size < 3) return null;
      const got = shuffle([...reg, ...irr], rng);
      if (lv >= 2 && !kindsOk(got.map((v) => v.kind).join(''))) return null;
      const pasts = new Set(got.map((v) => v.p));
